SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/1077369385e2f45f53fcb123c439df6b8e4a0f85/content/books/zizhi-tongjian/vol-294/year-0959/part-03/sources/library/jiuwudaishi-119-zhangzhao-litao/source.txt", "note": "《旧五代史》卷一百十九，段落 jiu-wudaishi-205deb4a7860-p002803；EPUB电子本，纸本及异文待核", "id": "15bc8b15-ee9c-53ac-995d-0795c421fee3"}, {"title": "旧五代史·卷一百二十", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/1077369385e2f45f53fcb123c439df6b8e4a0f85/content/books/zizhi-tongjian/vol-294/year-0959/part-03/sources/library/jiuwudaishi-120-gongdi-accession/source.txt", "note": "《旧五代史》卷一百二十，段落 jiu-wudaishi-205deb4a7860-p002809；EPUB电子本，纸本及异文待核", "id": "edb9a7d7-24df-53fe-8997-39422feae7da"}, {"title": "旧五代史·卷一百二十", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/1077369385e2f45f53fcb123c439df6b8e4a0f85/content/books/zizhi-tongjian/vol-294/year-0959/part-03/sources/library/jiuwudaishi-120-july-959/source.txt", "note": "《旧五代史》卷一百二十，段落 jiu-wudaishi-205deb4a7860-p002810；EPUB电子本，纸本及异文待核", "id": "4dc6764a-7262-5b65-8db6-206d0bb27c64"}, {"title": "宋史·巻二百四十九", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/1077369385e2f45f53fcb123c439df6b8e4a0f85/content/books/zizhi-tongjian/vol-294/year-0959/part-03/sources/library/songshi-249-weirenpu-chancellor/source.txt", "note": "《宋史》巻二百四十九，段落 songshi-9c6e46fee832-p057137；EPUB电子本，纸本及异文待核", "id": "55df1929-bdd0-5db9-b120-6c1758d3b4e6"}, {"title": "宋史·巻二百六十九", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/1077369385