INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "留从效", "aliases": ["留從效", "留從効"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "泉州散员指挥使，主书称桃林人，《宋史》记泉州永春人。944年参与杀黄绍颇、迎王继勋，并任都指挥使。新史写留從効，沿用同一主体。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "55786b2f-a228-5281-a323-e9c521b2988f"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "李从善", "aliases": ["李從善"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李璟之子，南唐纪公。959年与钟谟奉使后周。《旧五代史》记六月赐江南进奉使李从善钱、绢、银。生卒年未核，亲属关系据通鉴明确其子，不依宋史王著传中其弟的疑似误记另建关系。", "biography": null, "status": "draft", "id": "5ab72e0d-a78d-54e7-9ac2-7d34f9d7c58d"}, {"name": "钟谟", "aliases": ["鍾謨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "会稽人，南唐吏部郎中。949年条下与李德明一起参与国政，史书称两人以辩才聪慧受到李璟宠信。与后文同名外交官的进一步经历按年代续录，生卒年尚未录入。", "biography": null, "status": "draft", "id": "ee7c4ab6-a8d3-5f0a-8b05-ede060c3934c"}, {"name": "李存勖", "aliases": ["李存勗", "李亚子", "后唐庄宗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "908年继承晋王之位，923年在魏州称帝，国号唐；同年率军灭后梁。", "biography": "908年继承晋王之位，923年在魏州称帝，国号唐；同年率军灭后梁。", "status": "draft", "id": "4e068da9-c8dd-5a31-a747-87669e3bf993"}, {"name": "王环（后蜀凤州节度使）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "镇州真定人，早年以勇力为孟知祥御者，后掌后蜀宿卫。开运末秦凤等地入蜀后，孟昶任其为凤州节度使。955年十一月凤州陷落时被后周军俘获。与914—929年楚水军将领王环分别保存，无同人证据。生卒年未载。", "biography": null, "status": "draft", "id": "abfc7768-1b27-5f09-bc3e-db6360a31dd2"}, {"name": "刘仁赡", "aliases": ["劉仁贍"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领，刘金之子，字守惠、彭城人。951年以武昌节度使身份率二百艘战舰攻取岳州。《新五代史》还记他早年任左监门卫将军、黄袁二州刺史，后掌亲军。生卒年尚未录入。", "biography": null, "status": "draft", "id": "fbdf8a53-b985-5dda-a5d1-e96cf9d7121c"}, {"name": "严续", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷270贞明四年条所见人物：严续。", "biography": null, "status": "draft", "id": "57b5cb9f-cb31-5e6a-87de-6363e1836468"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "张美", "aliases": ["張美"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "清河人，后周枢密院承旨。《通鉴》记955年六月任右领军大将军、权点检三司事，《旧五代史》记八月任权判三司，任职月与称号差异分别保留。早年管理澶州隶属三司的财物，曾应柴荣私人所求而供给，郭威得知后将他调到濮州。", "biography": null, "status": "draft", "id": "e0ae365f-4a51-5f92-82eb-86e617f0d42b"}, {"name": "杨廷璋", "aliases": ["楊廷璋"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "真定人，后周建雄节度使。958年二月条下记隰州换守、与李谦溥协力夜袭北汉围军并奏报。《宋史》记其字温玉、姐姐曾为郭威淑妃，早年从郭威左右任军职。生卒年未载。", "biography": null, "status": "draft", "id": "55ed28fe-20db-5c62-a87b-0ae889fe4cc2"}, {"name": "符氏（柴荣继皇后）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "符彦卿之女、柴荣宣懿皇后的妹妹。959年六月癸未被立为皇后。与此前去世的宣懿皇后分别保存，个人名字及生卒年未载。", "biography": null, "status": "draft", "id": "b78b5e44-fd65-5978-a68a-69647771b75d"}, {"name": "符氏（柴荣宣懿皇后）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "符彦卿之女、符存审之孙女，先嫁李守贞之子李崇训。河中城陷时躲过丈夫的杀害，郭威将她送回父亲处；后嫁柴荣，954年四月被立为皇后。与柴荣后来所立符氏皇后区分；生卒年待后续相应史料校核。", "biography": null, "status": "draft", "id": "5fc1e8cd-d993-547b-a735-fe29fb2346df"}, {"name": "符彦卿", "aliases": ["符彥卿", "李彦卿", "李彥卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：符彦卿，散员都指挥使、力战者。", "biography": null, "status": "draft", "id": "c837916f-0fdf-5954-a190-597b08cd9402"}, {"name": "宗训（后周恭帝）", "aliases": ["宗训", "宗訓", "后周恭帝"], "era": "五代十国", "birth_year": 953, "death_year": null, "description": "柴荣之子，后周恭帝。《旧五代史》明确记广顺三年八月四日生于澶州府第，即953年。959年六月封梁王，柴荣去世后即位。史载七岁不等于现代周岁，此处沿主书名宗训加帝号限定，不与王宗训等同名人物混同。卒年未核。", "biography": null, "status": "draft", "id": "2ebb07e4-d163-5a1f-976b-a934249b4716"}, {"name": "宗让（柴荣子）", "aliases": ["宗让", "宗讓", "熙让", "熙讓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "柴荣之子。959年六月授左骁卫上将军，通鉴封号作燕王，新旧五代史作燕国公。新五代史又载八月更名熙让、封曹王，沿同一主体保存别名，改名事件留到相应连续段落。生卒年未载。", "biography": null, "status": "draft", "id": "2017dec1-e62f-59a1-992b-3f995a2ca6d6"}, {"name": "魏仁浦", "aliases": ["魏仁溥"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "字道济，卫州汲人。后晋末任枢密院小吏，随众被迁往契丹后逃归。947年在巩县迎见刘知远，因熟知军队人数与旧制受到郭威信任。生卒年尚未录入。", "biography": null, "status": "draft", "id": "c2e87754-6e6a-56db-b3e1-45835b2bff92"}, {"name": "王溥", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷262天复元年条所见人物：王溥。", "biography": null, "status": "draft", "id": "b8b4ff87-1c1f-5c80-bc6c-83b5a3b1164f"}, {"name": "范质", "aliases": ["范質", "範質"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "宗城人，后晋主客员外郎。944年六月戊辰任翰林学士。后续仕宦随编年主线补录。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "abe2c0af-4bf3-551b-83c9-f355ba085a0e"}, {"name": "吴廷祚", "aliases": ["吳廷祚", "吴延祚", "吳延祚"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "字庆之，并州太原人，早年为郭威亲校。959年二月以宣徽南院使身份与韩通督发丁夫浚汴水。新旧《五代史》又作吴延祚，按相同使职与留守任务关联，保留姓名异文。生卒年本段未核。", "biography": null, "status": "draft", "id": "8bc98a15-7a90-5881-b0f2-dd8e47a9d791"}, {"name": "韩通", "aliases": ["韓通"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后周保义军留后。954年正月正式任保义节度使，《旧五代史》以陕州留后称其前职。生卒年暂未核定。", "biography": null, "status": "draft", "id": "81e4d74c-3057-59e4-a9a3-5baa18bff059"}, {"name": "张永德", "aliases": ["張永德"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "阳曲人，郭威的女婿。950年任供奉官押班，奉命给昭义节度使常思送生日礼物；常思接到杀他的密诏后拘留观望，郭威取京师后释放并道歉。生卒年本批未录。", "biography": null, "status": "draft", "id": "c1584e5c-2a3c-5c28-bbe4-7c8a05161c51"}, {"name": "赵匡胤", "aliases": ["趙匡胤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周宿卫将领，后来成为宋太祖。954年高平之战右军溃逃后，与张永德分率两翼反击北汉军。《宋史》本纪印证其率同列冲锋的记载。生卒年留待相应史料补录。", "biography": null, "status": "draft", "id": "ce0fe2a6-d446-50c7-b968-4245fd9693ad"}, {"name": "张昭（五代宋初）", "aliases": ["张昭远", "張昭遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：张昭（五代宋初），河间推官、劝表并赞志者。", "biography": null, "status": "draft", "id": "0f1b47dc-df4b-5258-91b3-463432d576b7"}, {"name": "李涛", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：李涛。", "biography": null, "status": "draft", "id": "6d85380a-8ee9-587e-a411-db6354d07b6d"}, {"name": "李澣", "aliases": ["李浣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李涛的弟弟，后晋翰林学士。《资治通鉴》说他多次酒后失当，石敬瑭不喜欢他；940年九月翰林学士职务被撤销、事务归中书舍人。《旧五代史》同期学士名写李浣，另记他调吏部员外郎，保留字形说明。生卒年未载。", "biography": null, "status": "draft", "id": "cc1a8d2a-5333-5d3b-befa-dea7a7c759a6"}, {"name": "王著（后周翰林学士）", "aliases": ["王著（字成象）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "字成象，单州单父人，柴荣幕府旧僚。后周翰林学士，柴荣多次考虑任其为相，因嗜酒而未实行；959年临终又要求任他为相，范质等没有实行。与其他时代、职务的同名王著区分，生卒年未核。", "biography": null, "status": "draft", "id": "20c1d979-e858-5388-9e94-fa0e4172cd11"}, {"name": "李重进", "aliases": ["李重進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "沧州人，福庆长公主之子，郭威的外甥，生于太原。郭威在藩镇时期的将佐，952年任恩州团练使，逐渐受重用。《宋史》还记当年内殿职务变化，具体任日未载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9769d0fb-1d80-593e-9aa3-e4c22416f835"}, {"name": "向训", "aliases": ["向訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周军官。951年与陈思让参与虒亭战事，《旧五代史》称监军，《宋史》称都监。生卒年及后续改名尚未据本次引文录入。", "biography": null, "status": "draft", "id": "1d29bcb9-6ec9-5369-89ff-ea67f0460acc"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "留从效入贡，请在后周设进奏院并直属中朝", "start_year": 959, "end_year": 959, "time_original": "959年六月答诏以前，具体派遣日未载", "dynasty": "五代十国", "description": "留从效入贡，请在后周设进奏院并直属中朝。", "phases": [], "location_name": "清源至后周京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "65dabb80-a7f4-5d1d-83cc-f6dadbdfe747"}, {"title": "柴荣不准留从效设直属进奏院，劝继续奉事南唐", "start_year": 959, "end_year": 959, "time_original": "959年六月戊寅", "dynasty": "五代十国", "description": "柴荣不准留从效设直属进奏院，劝继续奉事南唐。", "phases": [], "location_name": "后周至清源", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c8ac2ec7-2ef3-57cf-a664-32a2d1fe91f8"}, {"title": "李璟派纪公李从善与钟谟奉使后周", "start_year": 959, "end_year": 959, "time_original": "959年六月条所记，具体到达日未载", "dynasty": "五代十国", "description": "李璟派纪公李从善与钟谟奉使后周。", "phases": [], "location_name": "南唐至后周", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "fbd02043-1539-5c19-bb22-4297f4c37e9f"}, {"title": "柴荣问南唐是否整军设防，钟谟答不敢", "start_year": 959, "end_year": 959, "time_original": "959年李从善、钟谟使周时，具体问答日未载", "dynasty": "五代十国", "description": "柴荣问南唐是否整军设防，钟谟答不敢。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "d51ede2f-a271-53d1-813d-0d14126a2f1d"}, {"title": "柴荣劝李璟及时修城整军，为后代守国作准备", "start_year": 959, "end_year": 959, "time_original": 