SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "留从效入贡，请在后周设进奏院并直属中朝。", "citation": "卷294·显德五年（959年六月至七月及相关追述、史论）·zztj-v294-y0959-p021·原文件第89行", "note": "原文：唐清源节度使留从效遣使入贡，请置进奏院于京师，直隶中朝。；核对说明：这次请求与958年入贡、请求直属的记录分开，未具名使者不擅定为同一人。", "status": "draft", "id": "8fdf0010-01b9-501c-81da-4c79fa0838af", "subject_id": "65dabb80-a7f4-5d1d-83cc-f6dadbdfe747", "source_id": "369bb07b-44cd-5100-9c00-fe3945faf928"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "959年六月答诏以前，具体派遣日未载", "citation": "卷294·显德五年（959年六月至七月及相关追述、史论）·zztj-v294-y0959-p021·原文件第89行", "note": "原文：唐清源节度使留从效遣使入贡，请置进奏院于京师，直隶中朝。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "21d6bfd7-c46b-5276-a277-c172436b3317", "subject_id": "65dabb80-a7f4-5d1d-83cc-f6dadbdfe747", "source_id": "369bb07b-44cd-5100-9c00-fe3945faf928"}, {"subject_table": "person", "field_path": "description", "claim_text": "留从效：派使入贡，请设进奏院并改为直接隶属后周。", "citation": "卷294·显德五年（959年六月至七月及相关追述、史论）·zztj-v294-y0959-p021·原文件第89行", "note": "原文：唐清源节度使留从效遣使入贡，请置进奏院于京师，直隶中朝。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "9e6a1cca-6cfa-552e-b0b7-12b9ca4c3f1b", "subject_id": "55786b2f-a228-5281-a323-e9c521b2988f", "source_id": "369bb07b-44cd-5100-9c00-fe3945faf928"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "留从效：派使入贡，请设进奏院并改为直接隶属后周。", "citation": "卷294·显德五年（959年六月至七月及相关追述、史论）·zztj-v294-y0959-p021·原文件第89行", "note": "原文：唐清源节度使留从效遣使入贡，请置进奏院于京师，直隶中朝。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "f60d41fc-51a0-5de2-82a8-60fb31c86340", "subject_id": "e33ca70d-61b0-5226-bb11-c68ebb623380", "source_id": "369bb07b-44cd-5100-9c00-fe3945faf928"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》五月条记留从效派别驾王禹锡至行在入贡，柴荣不愿夺南唐所属，只下诏褒美。", "citation": "《旧五代史》卷一百十九，段落 jiu-wudaishi-205deb4a7860-p002800；EPUB电子本，纸本及异文待核", "note": "原文：泉州節度使劉從效遣別駕王禹錫奉貢於行在，帝以泉州比臣江南，李景方歸奉國家，不欲奪其所屬，但錫詔褒美而已。；核对说明：《旧五代史》五月行在入贡与《资治通鉴》六月答诏可能是相关使事的不同阶段，尚不能确定完全同一次往返。刘从效为该书姓氏异文；王禹锡不与既有黄禹锡未经证据合并，也不直接补为《资治通鉴》未名使者。", "status": "draft", "id": "c1087b99-b57b-5bfd-818f-1ef6ef127544", "subject_id": "65dabb80-a7f4-5d1d-83cc-f6dadbdfe747", "source_id": "29ee8211-c4ac-549b-9af7-ca29e34fcc8f"}, {"subject_table": "event", "field_path": "description", "claim_text": "柴荣不准留从效设直属进奏院，劝继续奉事南唐。", "citation": "卷294·显德五年（959年六月至七月及相关追述、史论）·zztj-v294-y0959-p021·原文件第89行", "note": "原文：戊寅，诏报以“江南近服，方务绥怀，卿久奉金陵，未可改图。若置邸上都，与彼抗衡，受而有之，罪在于朕。卿远修职贡，足表忠勤，勉事旧君，且宜如故。如此，则于卿笃始终之义，于朕尽柔远之宜，惟乃通方，谅达予意，”；核对说明：反对另设进奏院是维护既有南唐隶属，不把接受贡品写成已建立确定直属后周关系。", "status": "draft", "id": "525c9956-bf71-565e-af24-d00cc2b9470b", "subject_id": "c8ac2ec7-2ef3-57cf-a664-32a2d1fe91f8", "source_id": "369bb07b-44cd-5100-9c00-fe3945faf928"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "959年六月戊寅", "citation": "卷294·显德五年（959年六月至七月及相关追述、史论）·zztj-v294-y0959-p021·原文件第89行", "note": "原文：戊寅，诏报以“江南近服，方务绥怀，卿久奉金陵，未可改图。若置邸上都，与彼抗衡，受而有之，罪在于朕。卿远修职贡，足表忠勤，勉事旧君，且宜如故。如此，则于卿笃始终之义，于朕尽柔远之宜，惟乃通方，谅达予意，”；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "2c404049-f32d-5709-a4bf-2235c7fe917f", "subject_id": "c8ac2ec7-2ef3-57cf-a664-32a2d1fe91f8", "source_id": "369bb07b-44cd-5100-9c00-fe3945faf928"}, {"subject_table": "person", "field_path": "description", "claim_text": "柴荣：以南唐新近臣服为由拒绝改隶，劝留从效继续事旧君。", "citation": "卷294·显德五年（959年六月至七月及相关追述、史论）·zztj-v294-y0959-p021·原文件第89行", "note": "原文：戊寅，诏报以“江南近服，方务绥怀，卿久奉金陵，未可改图。若置邸上都，与彼抗衡，受而有之，罪在于朕。卿远修职贡，足表忠勤，勉事旧君，且宜如故。如此，则于卿笃始终之义，于朕尽柔远之宜，惟乃通方，谅达予意，”；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "ec41c1bd-abd3-5815-8658-ea4e70205b8f", "subject_id": "697c1a4f-b373-5a78-8b47-330fe349a424", "source_id": "369bb07b-44cd-5100-9c00-fe3945faf928"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "柴荣：以南唐新近臣服为由拒绝改隶，劝留从效继续事旧君。", "citation": "卷294·显德五年（959年六月至七月及相